#include <stdio.h>
#include <string.h>
static char g_log[64];
static void Log(const char* s) { strcat(g_log, s); }
struct CIntelligentPointer { const char* Tag; CIntelligentPointer(const char* t) : Tag(t) { } ~CIntelligentPointer() { Log(Tag); } };
